// Public full-bleed icon assets. The operating system applies its own mask.
const currentIcons: Record<string,string> = {"devocional-180-v2.png":"","devocional-192-v2.png":"","devocional-512-v2.png":""};
currentIcons["devocional-maskable-512-v2.png"] = currentIcons["devocional-512-v2.png"];
export const appIcons: Record<string,string> = {...currentIcons};
for (const [name, data] of Object.entries(currentIcons)) appIcons[name.replace("-v2.png", ".png")] = data;
